          <ChartCard
            title="Queue stock & unlock band"
            subtitle={`>${fmtGw(HEADLINE.globalQueueStalledGw)} stalled; unlock ${fmtGw(HEADLINE.unlockTotalGwLow)}???${fmtGw(HEADLINE.unlockTotalGwHigh)}`}
